import numpy as np, itertools
L=np.log(eps)
Epool={'1':np.ones_like(eps),'L':L,'1/e':1/eps,'e':eps,'L2':L**2}
Tpool={'1':np.ones_like(T),'T':T,'T2':T**2,'T3':T**3,'1/T':1/T,'1/T2':1/T**2,'expT':np.exp(T),'exp-T':np.exp(-T),'logT':np.log(T),'T4':T**4,'sqrtT':np.sqrt(T)}
terms=list(Epool)
# start: each eps term with full T basis set of 1,T,T2
sel={e:['1','T','T2'] for e in terms}
def build(sel):
    cols=[];nm=[]
    for e in terms:
        for t in sel[e]:
            cols.append(Epool[e]*Tpool[t]); nm.append(e+'*'+t)
    return np.array(cols).T,nm
def err(sel):
    A,_=build(sel); c=np.linalg.lstsq(A,sigma,rcond=None)[0]
    return np.mean((A@c-sigma)**2)/np.var(sigma)
for it in range(3):
    for e in terms:
        best=None
        for k in [2,3]:
            for combo in itertools.combinations(list(Tpool),k):
                s2=dict(sel); s2[e]=list(combo)
                v=err(s2)
                if best is None or v<best[0]: best=(v,list(combo))
        sel[e]=best[1]
    print(it,{e:sel[e] for e in terms}, err(sel))
